data.query:
query Query(
  $d: WorkOrderProcessDistributionWhereInput,
  $ps: ProductStrategyWhereInput
) {
  d:workOrderProcessDistribution(where: $d) {
    edges {
      node {
        id
        distributionGroupId
        balanceQuantity
        workOrder {id number}
        workOrderProcessId
        workcenterId
        earliestStartAt
        latestStartAt
        estimatedTime
        workOrderProcess {
          productStrategyProcessId 
        }
      }
    }
  }
  ps:productStrategy(where:$ps){
    edges{node{
      id code 
      strategyProcesses{edges{node{
        id
        processId
        standardRate
        setupRate
        setupOperators
        productionOperators

        assemblyBoms{edges{node{
          id
          laborUsage 
          machineUsage 
          standardUsage
          unitPerCycle
          standardPackQuantity
          componentProductStrategyId
          componentProductId
          componentProductStrategyProcessId
          bomTypeId
        }}}
      }}}
    }}
  }
}

data.transform:
(
  $ps := ps.edges.node;
  $psp := $ps.strategyProcesses.edges[0].node;
  $d := d.edges.node;
  $id := $cuid();
  $did := $cuid();
  $wid := $cuid();
  $wpid := $cuid();
  $ls := $sort([$d.latestStartAt[$!=null]], function($l, $r) {
    $l > $r
  })[0];
  $es := $sort([$d.earliestStartAt[$!=null]], function($l, $r) {
    $l > $r
  })[0];

  {
    "dg": {
      "create": {
        "id": $id,
        "balanceQuantity": $sum($d.balanceQuantity),
        "requiredQuantity": $sum($d.balanceQuantity),
        "parallelPositions":true,
        "workOrderProcessDistributionStatusId": "New",
        "workcenterId": $d[0].workcenterId,
        "standardRate": $psp.standardRate,
        "setupRate": $coalesce([$psp.setupRate,0]),
        "idealRate": $coalesce([$psp.idealRate,$psp.standardRate]),
        "estimatedTime": ($isNilOrEmpty($psp.standardRate) or $psp.standardRate=0? 0 : $sum($d.balanceQuantity) / $psp.standardRate) + $coalesce([$psp.setupRate,0]),
        "customData": {
          "sharedComponents": $ps[0].strategyProcesses.edges[0].node.assemblyBoms.edges.node[bomTypeId='Product']
        }
      }
    },
    "dc": {
      "create": {
        "id": $did,
        "distributionGroupId": $id,
        "leadingProduct": true,
        "virtual": true,
        "balanceQuantity": $sum($d.balanceQuantity),
        "requiredQuantity": $sum($d.balanceQuantity),
        "workOrderProcessDistributionStatusId": "New",
        "workcenterId": $d[0].workcenterId,
        "parentProcessId": $ps[0].strategyProcesses.edges[0].node.id,
        "standardRate": $psp.standardRate,
        "setupRate": $coalesce([$psp.setupRate,0]),
        "idealRate": $coalesce([$psp.idealRate,$psp.standardRate]),
        "estimatedTime": ($isNilOrEmpty($psp.standardRate) or $psp.standardRate=0? 0 : $sum($d.balanceQuantity) / $psp.standardRate) + $coalesce([$psp.setupRate,0])
      }
    },
     "du": $d.(
      $p := workOrderProcess.productStrategyProcessId;
    {
      "update": {
        "distributionGroupId": $id,
        "leadingDistributionId": $did,
        "laborUsage":$psp.assemblyBoms.edges.node[componentProductStrategyProcess=$p].laborUsage,
        "machineUsage": $psp.assemblyBoms.edges.node[componentProductStrategyProcess=$p].machineUsage,
        "materialUsage": $psp.assemblyBoms.edges.node[componentProductStrategyProcess=$p].standardUsage
      },
      "where": {
        "id":id
      }
    }
    )
  }


)

