(
  $g := g.edges.node;
  $d := d.edges.node;
  $fromDistributionGroupUpdatePayload := $d.distributionGroup.distributions.total > 1?(
    $remainingDistributions := $d.distributionGroup.distributions.edges.node[id != $d.id];
    $totalProduced := $sum( $remainingDistributions.producedQuantity);
    $totalRequired := $sum( $remainingDistributions.requiredQuantity);
    [
      {
        "where":{"id": $d.distributionGroup.id},
        "update":{
          "balanceQuantity": $sum($remainingDistributions.balanceQuantity),
          "requiredQuantity": $totalRequired ,
          "estimatedTime": $sum($remainingDistributions.estimatedTime),
          "producedQuantity": $totalProduced ,
          "scrappedQuantity": $sum($remainingDistributions.scrappedQuantity),
          "percentComplete": $totalProduced / $totalRequired
        }
      }
    ]
  ):
  [];

  {
    "dg": $g.{
      "update": {
        "balanceQuantity": balanceQuantity + $d.balanceQuantity,
        "requiredQuantity": requiredQuantity + $d.requiredQuantity,
        "estimatedTime": estimatedTime + $d.estimatedTime,

        "producedQuantity": producedQuantity + $d.producedQuantity,
        "scrappedQuantity": scrappedQuantity + $d.scrappedQuantity,
        "percentComplete": (producedQuantity + $d.producedQuantity) / (requiredQuantity + $d.requiredQuantity)
      },
      "where": {
        "id": id
      }
    },

    "du": $d.{
      "update": {
        "distributionGroupId": $g.id
      },
      "where": {
        "id":id
      }
    },
    "fromDistributionGroupUpdatePayload": $fromDistributionGroupUpdatePayload,
    "distributionGroupDeletePayload":[
      $d.distributionGroup.distributions.total = 1?{
        "where":{ "id":  $d.distributionGroup.id } 
      }
    ]
  }


)

(
  $g := g.edges.node;
  $d := d.edges.node;
  $id := $state.context.REQUEST.DATA.id;
  $dgid := $cuid();

  {
    "dg":  $g.{
      "update": {
        "balanceQuantity": balanceQuantity - $d.balanceQuantity,
        "requiredQuantity": requiredQuantity - $d.requiredQuantity,
        "estimatedTime": estimatedTime - $d.estimatedTime
      },
      "where": {
        "id": id
      }
    } ,

    "du": $d.{
      "update": {
        "distributionGroupId": $dgid
      },
      "where": {
        "id":id
      }
    },


    "dc": {
      "create": $merge([$omit($d,["id","workOrder","workOrderProcess","distributionGroupId"]),{"id":$dgid}])
    }
  }


)

